const fs = require('fs');
const path = require('path');

const rootDir = path.resolve(__dirname, '..');
const releaseDir = path.join(rootDir, 'release');

function ensureDir(dirPath) {
  fs.mkdirSync(dirPath, { recursive: true });
}

function emptyDir(dirPath) {
  if (fs.existsSync(dirPath)) {
    fs.rmSync(dirPath, { recursive: true, force: true });
  }
  ensureDir(dirPath);
}

function copyFile(src, dest) {
  ensureDir(path.dirname(dest));
  fs.copyFileSync(src, dest);
}

function copyDir(src, dest) {
  ensureDir(dest);
  fs.cpSync(src, dest, { recursive: true });
}

function mustExist(relativePath) {
  const abs = path.join(rootDir, relativePath);
  if (!fs.existsSync(abs)) {
    throw new Error(`Required path not found: ${relativePath}. Run npm run build first.`);
  }
  return abs;
}

function writeReleaseReadme() {
  const content = [
    '# Billing release bundle',
    '',
    'Generated by `npm run release:bundle`.',
    '',
    '## Start with PM2',
    '1. `cd release`',
    '2. `npm --prefix backend ci --omit=dev`',
    '3. `pm2 start pm2.config.cjs`',
    '',
    '## Start without PM2',
    '1. `cd release/backend`',
    '2. `npm ci --omit=dev`',
    '3. `node dist/index.js`',
    '',
    '## Notes',
    '- Backend serves frontend static files from `../frontend/dist`.',
    '- Put production values in `release/backend/.env`.',
  ].join('\n');

  fs.writeFileSync(path.join(releaseDir, 'README.md'), content, 'utf8');
}

function buildManifest() {
  const manifest = {
    generatedAt: new Date().toISOString(),
    contents: [
      'backend/dist',
      'backend/package.json',
      'backend/package-lock.json',
      'backend/.env.example',
      'backend/.env.production',
      'frontend/dist',
      'pm2.config.cjs',
      'README.md'
    ]
  };

  fs.writeFileSync(
    path.join(releaseDir, 'release.manifest.json'),
    JSON.stringify(manifest, null, 2),
    'utf8'
  );
}

function main() {
  const backendDist = mustExist('backend/dist');
  const frontendDist = mustExist('frontend/dist');

  emptyDir(releaseDir);

  copyDir(backendDist, path.join(releaseDir, 'backend', 'dist'));
  copyDir(frontendDist, path.join(releaseDir, 'frontend', 'dist'));

  copyFile(path.join(rootDir, 'backend', 'package.json'), path.join(releaseDir, 'backend', 'package.json'));
  copyFile(path.join(rootDir, 'backend', 'package-lock.json'), path.join(releaseDir, 'backend', 'package-lock.json'));
  copyFile(path.join(rootDir, 'backend', '.env.example'), path.join(releaseDir, 'backend', '.env.example'));

  const envProd = path.join(rootDir, 'backend', '.env.production');
  if (fs.existsSync(envProd)) {
    copyFile(envProd, path.join(releaseDir, 'backend', '.env.production'));
  }

  ensureDir(path.join(releaseDir, 'backend', 'uploads'));

  copyFile(path.join(rootDir, 'pm2.config.cjs'), path.join(releaseDir, 'pm2.config.cjs'));

  writeReleaseReadme();
  buildManifest();

  console.log('[release] Bundle generated at:', releaseDir);
}

main();
